# Render code-drawn layout mockups when a browser screenshot is unavailable.
# These are proposals, not captures of an implemented WPF application.
param([switch]$Compact)
Add-Type -AssemblyName System.Drawing
Add-Type -ReferencedAssemblies System.Drawing -TypeDefinition @'
using System;
using System.Drawing;
using System.Drawing.Drawing2D;
using System.Drawing.Imaging;
public static class CellQMockups {
 static Graphics g; static string navy="#001D50", blue="#0067BF", outline="#003378", gray="#555555", canvas="#E6E6E6";
 static Color C(string h){return ColorTranslator.FromHtml(h);}
 static void Box(float x,float y,float w,float h,string color,string border=null){using(var b=new SolidBrush(C(color)))g.FillRectangle(b,x,y,w,h);if(border!=null)using(var p=new Pen(C(border)))g.DrawRectangle(p,x,y,w,h);}
 static void Text(string text,float x,float y,float size=14,string color=null,bool bold=false,string family="Segoe UI"){using(var f=new Font(family,size,bold?FontStyle.Bold:FontStyle.Regular,GraphicsUnit.Pixel))using(var b=new SolidBrush(C(color??navy)))g.DrawString(text,f,b,x,y);}
 static void Badge(string text,float x,float y,float w,string fill="#FFFFFF",string color="#555555"){Box(x,y,w,25,fill,"#A6A6A6");Text(text,x+8,y+5,11,color,true);}
 static void Button(string text,float x,float y,float w){Box(x,y,w,33,"#FFFFFF","#A6A6A6");Text(text,x+10,y+8,12,gray);}
 static void Nav(float x,float y,float w,bool compact=false,bool horizontal=false){string[] names={"Device","Data Logs","Firmware Update","Diagnostics"};string[] icons={"▣","▤","↑","⌁"};for(int i=0;i<4;i++){float nx=horizontal?x+i*177:x,ny=horizontal?y:y+i*48,nw=horizontal?169:w;if(i==1){Box(nx,ny,nw,44,blue);Box(nx,ny+9,3,26,"#00ACC0");}Text(icons[i],nx+12,ny+10,18,i==1||!compact?"#FFFFFF":navy);Text(names[i],nx+43,ny+13,compact?12:14,i==1||!compact?"#FFFFFF":navy,true);}}
 static void Detail(float x,float y,float w,bool full){Box(x,y,w,full?392:122,"#FFFFFF","#A6A6A6");Text("Selected sample",x+18,y+17,14,null,true);Badge("Preview",x+w-78,y+13,60);Text("▤",x+18,y+58,26,blue);Text("sample_001.csv",x+58,y+60,13,null,true,"Consolas");Text("Local copy · illustrative only",x+58,y+81,11,gray);if(full){Text("Source folder",x+18,y+121,12,gray);Text("/DATA/20261008/",x+18,y+143,12,null,false,"Consolas");Text("File size",x+18,y+176,12,gray);Text("124 KB (sample)",x+18,y+198,12,null,false,"Consolas");Text("Verification",x+18,y+231,12,gray);Text("✓ Verified (sample)",x+18,y+253,12);Text("Completed downloads require frame,",x+18,y+289,11,gray);Text("offset, size, stream CRC, and",x+18,y+306,11,gray);Text("whole-file checks.",x+18,y+323,11,gray);Button("Open local copy",x+18,y+348,w-36);}else Button("Open local copy",x+w-154,y+63,136);}
 static void Progress(float x,float y,float w){Box(x,y,w,122,"#FFFFFF","#A6A6A6");Text("Transfer progress example",x+18,y+17,13,null,true);Badge("Sample state",x+w-108,y+13,90);Text("Verifying local copy · sample_001.csv",x+18,y+53,12);Box(x+18,y+79,w-36,6,canvas);Box(x+18,y+79,(w-36)*.68f,6,blue);Text("Illustrative progress · no transfer in progress",x+18,y+96,10,gray);}
 static void Table(float x,float y,float w,bool compact){Box(x,y,w,compact?306:322,"#FFFFFF","#A6A6A6");Text("Local copies",x+16,y+18,13,null,true);if(!compact)Text("4 sample files",x+100,y+20,10,gray);Text("Device logs",x+(compact?126:198),y+18,13,gray);Box(x+16,y+51,83,3,blue);Box(x+w-194,y+12,178,29,"#F8FCF8","#A6A6A6");Text("⌕  Filter by filename",x+w-182,y+19,11,gray);Box(x,y+54,w,38,"#F8FCF8");float file=x+48,folder=x+w*.43f,size=x+w*.62f,state=x+w*.73f;Text("□",x+15,y+65,12);Text("Filename",file,y+65,12,null,true);Text("Folder",folder,y+65,12,null,true);Text("Size",size,y+65,12,null,true);Text("Local verification",state,y+65,12,null,true);string[] fn={"sample_001.csv","sample_002.csv","sample_003.csv.part","sample_004.csv"};string[] dirs={"20261008","20261008","20261007","NO_RTC"};string[] sizes={"124 KB","86 KB","42 KB","18 KB"};string[] states={"✓ Verified · sample","✓ Verified · sample","Ⅱ Incomplete · sample","! Check failed · sample"};for(int i=0;i<4;i++){float yy=y+92+i*(compact?44:48);Box(x,yy,w,compact?44:48,i==0?canvas:"#FFFFFF");Box(x,yy+(compact?43:47),w,1,canvas);Text(i==0?"☑":"□",x+15,yy+15,12);Text(fn[i],file,yy+15,12,null,false,"Consolas");Text(dirs[i],folder,yy+15,12,gray,false,"Consolas");Text(sizes[i],size,yy+15,12,gray,false,"Consolas");Badge(states[i],state,yy+10,w*.25f,i<2?"#C5E3C1":i==2?"#FCBF71":"#FFBDBD",i<2?"#0F7900":i==2?navy:"#D70000");}Text("4 illustrative files · 1 selected",x+16,y+(compact?280:296),11,gray);Text("Device listing unavailable",x+w-162,y+(compact?280:296),11,gray);}
