 float ribbonY=144;if(top){Box(32,144,1376,52,outline);Nav(52,148,165,false,true);Text("⚙  Settings",1170,161,13,"#FFFFFF",true);Text("?  Help",1290,161,13,"#FFFFFF",true);ribbonY+=52;}
 Box(32,ribbonY,1376,80,"#FFFFFF","#A6A6A6");Text("CONNECTION",52,ribbonY+10,10,gray,true);Box(52,ribbonY+31,185,33,"#F8FCF8","#A6A6A6");Text("No device selected     ⌄",62,ribbonY+40,12,gray);Button("Connect",245,ribbonY+31,82);Box(347,ribbonY+16,1,48,canvas);Text("DATA LOGS",368,ribbonY+10,10,gray,true);Button("↻ Refresh",368,ribbonY+31,94);Button("↓ Download selected",470,ribbonY+31,158);Text("Preview only · actions unavailable",1181,ribbonY+33,11,gray);
 float bodyY=ribbonY+80,x=32,w=1376;if(top){Box(32,bodyY,1376,47,"#F8FCF8","#A6A6A6");Text("▣   No connected device       Firmware —",62,bodyY+15,12);Badge("○ Disconnected",1263,bodyY+10,125);bodyY+=47;}else{float sw=compact?184:220;Box(32,bodyY,sw,1000-bodyY,compact?"#FFFFFF":outline);Text("WORKSPACE",58,bodyY+25,10,compact?blue:"#FFFFFF",true);Nav(44,bodyY+56,sw-24,compact);Text("⚙   Settings",58,783,13,compact?navy:"#FFFFFF",true);Text("?   Help",58,825,13,compact?navy:"#FFFFFF",true);Box(58,872,sw-52,1,"#A6A6A6");Text("DEVICE",58,890,10,compact?blue:"#FFFFFF",true);Text("No connected device",58,910,12,compact?navy:"#FFFFFF",true);Text("Firmware version —",58,932,11,compact?gray:"#FFFFFF");Badge("○ Disconnected",58,958,132);x+=sw;w-=sw;}
 float px=x+(compact?24:30),py=bodyY+(top?20:26),pw=w-(compact?48:60);Text("MAINTENANCE WORKSPACE",px,py,10,blue,true);Text("Data Logs",px,py+20,26,null,true);Text("Browse device logs and review verified local copies.",px,py+58,14,gray);Badge("Sample content",px+pw-112,py+30,112);
 float ny=py+92;Box(px,ny,pw,62,"#F8FCF8");Box(px,ny,3,62,"#00ACC0");Text("ⓘ",px+17,ny+20,18,outline);Text("Design preview — no device connected",px+48,ny+13,13,null,true);Text("All filenames, sizes, and verification states below are illustrative samples.",px+48,ny+35,12,gray);
 float ty=ny+82;if(compact){float tw=pw-284;Table(px,ty,tw,true);Progress(px,ty+322,tw);Detail(px+tw+16,ty,268,true);}else{Table(px,ty,pw,false);float dw=(pw-18)*.56f;Detail(px,ty+340,dw,false);Progress(px+dw+18,ty+340,pw-dw-18);}
 Box(32,1000,1376,34,"#FFFFFF","#A6A6A6");Text("●  Disconnected   |   No device session",48,1010,11,gray);Text("Sample preview   |   No hardware operations",1152,1010,11,gray);Text("Segoe UI · 14 px body / 26 px title · Consolas for file details",32,1054,12,gray);string[] colors={navy,blue,"#00ACC0",canvas};string[] labels={"Navy","Blue","Cyan","Canvas"};for(int i=0;i<4;i++){Box(1090+i*79,1054,14,14,colors[i],"#A6A6A6");Text(labels[i],1110+i*79,1052,12,gray);}bitmap.Save(System.IO.Path.Combine(root,"docs","design","option-"+id+".png"),ImageFormat.Png);g.Dispose();}
