'@
$workspaceRoot = Split-Path (Split-Path $PSScriptRoot -Parent) -Parent
if ($Compact) { [CellQMockups]::RenderCompact($workspaceRoot) }
else { foreach ($designChoice in @('a','b','c')) { [CellQMockups]::Render($workspaceRoot,$designChoice) } }
